    if(workingTask()){const payload={content};payload.request_key=submissionKey(payload);await api(`/admin/ai/conversations/${encodeURIComponent(conversationID)}/steer`,'POST',payload)}
    else if(['image','video'].includes(mode)){if(attachments.length)throw new Error('图片和视频创作暂不接收附件，请先移除附件');const payload={conversation_id:conversationID,provider_id:form.elements.service.value,model:form.elements.provider.value,capability:mode,filename:form.elements.filename.value||'创作素材',prompt:content,seconds:mode==='video'?Number(form.elements.seconds.value):0};payload.request_key=submissionKey(payload);await api('/admin/ai/media','POST',payload)}
